impl ScopeContinuityCard7{pub fn validate(&self)->Result<(),ScopeContinuityError>{if self.schema_version!="1.0.0"||!ne(&self.contract_version)||!ne(&self.feature_id)||!ne(&self.mode)||!ne(&self.scale)||!ne(&self.request_id)||!ne(&self.purpose)||self.boundary!=BOUNDARY||!self.raw_data_local||!self.aggregate_only||self.assertion_order.is_empty()||!ord(&self.assertion_order)||!ord(&self.accepted_order)||!ord(&self.rejected_order)||!ord(&self.unknown_order)||!ord(&self.omitted_order)||!ord(&self.scope_order)||!ord(&self.dimension_order)||!ord(&self.epoch_order)||!ord(&self.negative_evidence_order)||!dig(&self.replay_identity)||!dig(&self.continuity_digest)||self.artifact.content_type!=CONTENT_TYPE||self.artifact.content_hash!=self.continuity_digest||self.artifact.boundary!=BOUNDARY{return Err(ScopeContinuityError::Output("scope identity, ordering, locality, digest, or artifact is invalid".into()))}let ids=BTreeSet::from_iter(self.assertion_order.iter().cloned());let parts=self.accepted_order.iter().chain(&self.rejected_order).chain(&self.unknown_order).chain(&self.omitted_order).cloned().collect::<Vec<_>>();if ids.len()!=self.assertion_order.len()||parts.len()!=ids.len()||BTreeSet::from_iter(parts)!=ids{return Err(ScopeContinuityError::Output("assertion states do not partition".into()))}Ok(())}}
pub fn qualify(request:&ScopeContinuityRequest4,id:&str,version:&str,scale:&str,mode:&str)->Result<ScopeContinuityCard7,ScopeContinuityError>{if !ne(&request.request_id)||!ne(&request.purpose)||request.assertions.is_empty()||request.required_scope_order.is_empty()||request.required_dimension_order.is_empty()||!dig(&request.replay_identity)||request.boundary!=BOUNDARY||!request.raw_data_local||!request.aggregate_only||!ord(&request.required_scope_order)||!ord(&request.required_dimension_order)||!ord(&request.adversarial_events){return Err(ScopeContinuityError::Invalid("scope identity, requirements, digest, ordering, locality, or boundary is invalid".into()))}let mut rows=request.assertions.clone();rows.sort_by(|a,b|a.assertion_id.cmp(&b.assertion_id));let mut seen=BTreeSet::new();let mut order=Vec::new();let mut accepted=BTreeSet::new();let mut rejected=BTreeSet::new();let mut unknown=BTreeSet::new();let mut omitted=BTreeSet::new();let mut scopes=BTreeSet::new();let mut dimensions=BTreeSet::new();let mut epochs=BTreeSet::new();let mut negative=BTreeSet::new();let mut digests=BTreeSet::new();for a in &rows{if !seen.insert(a.assertion_id.clone())||!ne(&a.assertion_id)||!ne(&a.scope_id)||!ne(&a.dimension)||!ne(&a.value)||!dig(&a.evidence_digest)||!a.local||!a.aggregate_only{return Err(ScopeContinuityError::Invalid("assertion identity, digest, dimension, or locality is invalid".into()))}order.push(a.assertion_id.clone());scopes.insert(a.scope_id.clone());dimensions.insert(a.dimension.clone());epochs.insert(format!("{}:{}",a.scope_id,a.policy_epoch));digests.insert(a.evidence_digest.clone());if a.negative_result{negative.insert(format!("{}:negative-result",a.assertion_id));}if a.policy_epoch==0{unknown.insert(a.assertion_id.clone());}else if !request.required_scope_order.contains(&a.scope_id)||!request.required_dimension_order.contains(&a.dimension){rejected.insert(a.assertion_id.clone());}else if a.evidence_digest==request.replay_identity{omitted.insert(a.assertion_id.clone());}else{accepted.insert(a.assertion_id.clone());}}let global=!request.policy_allowed||!request.protected_closure||!request.signed_approval||!request.raw_data_local||!request.aggregate_only||!request.adversarial_events.is_empty()||request.action_count>request.action_budget;if global{omitted.extend(order.iter().cloned());accepted.clear();rejected.clear();unknown.clear();}let missing=!request.required_scope_order.iter().all(|s|scopes.contains(s))||!request.required_dimension_order.iter().all(|d|dimensions.contains(d));let disposition=if global{"blocked"}else if missing{"unknown"}else if !rejected.is_empty()||!unknown.is_empty()||!omitted.is_empty(){"partial"}else{"qualified"};let mut payload=json!({"schema_version":"1.0.0","contract_version":version,"feature_id":id,"mode":mode,"scale":scale,"request_id":request.request_id,"purpose":request.purpose,"disposition":disposition,"assertion_order":order,"accepted_order":accepted.into_iter().collect::<Vec<_>>(),"rejected_order":rejected.into_iter().collect::<Vec<_>>(),"unknown_order":unknown.into_iter().collect::<Vec<_>>(),"omitted_order":omitted.into_iter().collect::<Vec<_>>(),"scope_order":scopes.into_iter().collect::<Vec<_>>(),"dimension_order":dimensions.into_iter().collect::<Vec<_>>(),"epoch_order":epochs.into_iter().collect::<Vec<_>>(),"negative_evidence_order":negative.into_iter().collect::<Vec<_>>(),"replay_identity":request.replay_identity,"raw_data_local":true,"aggregate_only":true,"boundary":BOUNDARY});let digest=ContentHash::of_value(&payload).map_err(|e|ScopeContinuityError::Output(e.to_string()))?;payload["continuity_digest"]=json!(digest);payload["artifact"]=json!({"artifact_id":format!("scope-continuity:{}",request.request_id),"content_type":CONTENT_TYPE,"content_hash":digest,"semantic_loss":payload["omitted_order"],"assertion_digests":digests.into_iter().collect::<Vec<_>>(),"boundary":BOUNDARY});payload["effect_receipts"]=json!(if disposition=="qualified"{vec![format!("emit:scope-continuity-card:{}",request.request_id)]}else{vec!["block:unsafe-release".to_string()]});let out:ScopeContinuityCard7=serde_json::from_value(payload).map_err(|e|ScopeContinuityError::Output(e.to_string()))?;out.validate()?;Ok(out)}
